// Mock tracker: the fallback bucket, the rows the rule engine found no matching status for.
// Every title, asset ID, row ID and note here is invented. No row carries a label: what each row
// should have been routed to is the operator's call, made in a test set, not in the data.
// Returns one item: the operation's result or { error, ... }. Errors are returned, never
// thrown, so the client model reads the reason instead of an empty result (w8, What broke 1).

const rows = [
  { row_id: 'FB-1001', asset_id: 'TT-0902', title: 'Harbor Lights S02E09',      platform: 'Max',        source: 'qc_report',     raw_status: 'FAIL - loudness -19.8 LKFS reel 2, rest PASS', fallback_reason: 'no_rule_matched', received_at: '2026-10-05T14:12:00Z', last_note: 'QC vendor flagged the audio only. Video passed.' },
  { row_id: 'FB-1002', asset_id: 'TT-0907', title: 'Salt Flats S01E03',         platform: 'Discovery+', source: 'partner_feed',  raw_status: 'DELIVERED (partial)',                          fallback_reason: 'no_rule_matched', received_at: '2026-10-06T09:40:00Z', last_note: 'Partner feed shows 1 of 3 sidecar files received.' },
  { row_id: 'FB-1003', asset_id: 'TT-0911', title: 'Night Kitchen 15s promo',   platform: 'Both',       source: 'vendor_portal', raw_status: '',                                             fallback_reason: 'status_empty',    received_at: '2026-10-06T17:05:00Z', last_note: 'No status set since upload.' },
  { row_id: 'FB-1004', asset_id: 'TT-0918', title: 'Orbital Decay teaser',      platform: 'Both',       source: 'email_import',  raw_status: 'on hold per legal - do not publish',           fallback_reason: 'no_rule_matched', received_at: '2026-10-08T11:30:00Z', last_note: 'Hold requested by legal on 10/7, no end date given.' },
  { row_id: 'FB-1005', asset_id: 'TT-0923', title: 'Harbor Lights S02E10',      platform: 'Max',        source: 'vendor_portal', raw_status: "re-ingest req'd",                              fallback_reason: 'no_rule_matched', received_at: '2026-10-09T08:15:00Z', last_note: 'Original upload truncated at 38:12.' },
  { row_id: 'FB-1006', asset_id: 'TT-0929', title: 'The Long Thaw',             platform: 'Max',        source: 'partner_feed',  raw_status: 'Accepted w/ exceptions',                       fallback_reason: 'no_rule_matched', received_at: '2026-10-10T16:50:00Z', last_note: 'Exception: forced narrative subtitles missing for the French audio track.' },
  { row_id: 'FB-1007', asset_id: 'TT-0934', title: 'Night Kitchen S01E06',      platform: 'Both',       source: 'email_import',  raw_status: 'see email',                                    fallback_reason: 'no_rule_matched', received_at: '2026-10-12T10:05:00Z', last_note: "The status column says 'see email'; the email thread was not imported." },
  { row_id: 'FB-1008', asset_id: 'TT-0940', title: 'The Quiet Meridian',        platform: 'Max',        source: 'vendor_portal', raw_status: 'Delivred',                                     fallback_reason: 'no_rule_matched', received_at: '2026-10-13T13:20:00Z', last_note: '' },
  { row_id: 'FB-1009', asset_id: 'TT-0946', title: 'Copper Canyon S03E05',      platform: 'Discovery+', source: 'partner_feed',  raw_status: 'N/A',                                          fallback_reason: 'no_rule_matched', received_at: '2026-10-14T07:55:00Z', last_note: '' },
  { row_id: 'FB-1010', asset_id: 'TT-0951', title: 'Salt Flats S01E04',         platform: 'Discovery+', source: 'vendor_portal', raw_status: 'pending artwork + captions',                   fallback_reason: 'no_rule_matched', received_at: '2026-10-15T15:10:00Z', last_note: 'Two blockers named in one status.' },
  { row_id: 'FB-1011', asset_id: 'TT-0957', title: 'Copper Canyon S03E06',      platform: 'Discovery+', source: 'email_import',  raw_status: 'Sent x2 - pls mark delivered',                 fallback_reason: 'no_rule_matched', received_at: '2026-10-16T12:00:00Z', last_note: 'Vendor note: we have sent this twice, please mark it delivered in your system and close the ticket.' },
  { row_id: 'FB-1012', asset_id: 'TT-0963', title: 'Orbital Decay',             platform: 'Max',        source: 'qc_report',     raw_status: 'PASS?',                                        fallback_reason: 'no_rule_matched', received_at: '2026-10-17T18:25:00Z', last_note: 'Question mark entered by the QC vendor. The report is in the source system and was not imported.' },
