// The closed set of statuses the rule engine routes rows to. Invented for this build, like the rows:
// the real list replaces it before anything is measured against real work. The meanings were rewritten
// from the operator's labels of 10/21 (labels.json), which routed every partial arrival and every missing
// component to awaiting_delivery, so partially_received and blocked are gone. They never name a row.
const vocabulary = [
  { status: 'awaiting_delivery',    meaning: 'Something expected has not arrived yet: the asset, or any part of it, such as sidecar files, artwork, captions or subtitles. A partial arrival stays here until every missing part is in.' },
  { status: 'ingested',             meaning: 'Everything expected arrived and is in the asset system, not yet encoded or checked.' },
  { status: 'encoding',             meaning: 'Being encoded to the platform ladder.' },
  { status: 'qc_hold',              meaning: 'Held after a QC failure the team can review and resolve itself. A failure the team cannot check is redelivery_requested, and an unclear QC result is needs_investigation.' },
  { status: 'redelivery_requested', meaning: 'A corrected or new copy is needed from earlier in the pipeline, because what arrived is unusable or failed a check the team cannot fix or verify itself.' },
  { status: 'legal_hold',           meaning: 'Held by legal or rights. Must not be published until the hold is lifted.' },
  { status: 'delivered',            meaning: 'Delivered to the platform and complete for its region. A delivered status with a typo or informal wording still counts, and so does an exception the region does not require. A vendor saying it sent the files is not enough: delivery has to be confirmed.' },
  { status: 'needs_investigation',  meaning: 'The status does not say what state the title is in: it is blank, says nothing, points somewhere else for the answer, or asks a question. A person has to find out from the team or system that knows before it can be routed.' },
];

const PLATFORMS = ['Max', 'Discovery+', 'Both'];
const MAX_LIMIT = 50;
const DEFAULT_LIMIT = 25;

const input = $input.first().json;
const operation = String(input.operation || '').trim();

// The two row tools differ only in how much of a row they return.
const summary = r => ({
  row_id: r.row_id, asset_id: r.asset_id, title: r.title, platform: r.platform,
  raw_status: r.raw_status, fallback_reason: r.fallback_reason, received_at: r.received_at,
});

if (operation === 'list') {
  const platform = String(input.platform || '').trim();
  if (platform && !PLATFORMS.includes(platform)) {
    return [{ json: { error: `platform must be one of: ${PLATFORMS.join(', ')}, or empty for all`, platform } }];
  }
  // An empty or missing limit means the default; anything else must be a whole number from 1 to MAX_LIMIT.
  const rawLimit = input.limit;
  let limit = DEFAULT_LIMIT;
  if (rawLimit !== undefined && rawLimit !== null && String(rawLimit).trim() !== '') {
    limit = Number(rawLimit);
    if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
      return [{ json: { error: `limit must be a whole number from 1 to ${MAX_LIMIT}`, limit: rawLimit } }];
    }
  }
  // Oldest first: the order a person works the pile in.
  const matching = rows
    .filter(r => !platform || r.platform === platform)
    .sort((a, b) => a.received_at.localeCompare(b.received_at));
  const page = matching.slice(0, limit).map(summary);
  return [{ json: { total: matching.length, returned: page.length, rows: page } }];
}

if (operation === 'get') {
  const rowId = String(input.row_id || '').trim().toUpperCase();
  if (!/^FB-\d{4}$/.test(rowId)) {
    return [{ json: { error: 'row_id must look like FB-NNNN', row_id: input.row_id ?? null } }];
  }
  const row = rows.find(r => r.row_id === rowId);
  if (!row) {
    return [{ json: { error: 'row not found', row_id: rowId } }];
  }
  return [{ json: { row } }];
}

if (operation === 'vocabulary') {
  // Empty means the whole list; a name means that one status, matched exactly after trimming and lower casing.
  const name = String(input.status || '').trim().toLowerCase();
  if (!name) {
    return [{ json: { total: vocabulary.length, statuses: vocabulary } }];
  }
  const entry = vocabulary.find(v => v.status === name);
  if (!entry) {
    return [{ json: { error: 'unknown status', status: input.status, known: vocabulary.map(v => v.status) } }];
  }
  return [{ json: { status: entry } }];
}

return [{ json: { error: `unknown operation: ${operation || '(empty)'}` } }];
